using System;

namespace StdbModule;

public static partial class ArabicQuotes
{
    public static class أدونيس
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "الإنسان كلٌّ لا يتجزأ، والشعر، بوصفه التعبير الأعلى عن هوية الكائن الإنساني، لا يمكن أن ينفصل عن الفكر.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أن لبنان هو أكثر من جغرافيا. لبنان، كما أفهمه وأحبه، مشروع إنساني وحضاري، وثقافة تفيض عن حدوده؛ أو لأقل: هويَّته الإبداعية تتجاوز حدوده السياسية–الجغرافية.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "فكيف يستجلب العرب جميع الوسائل التي ابتكرتها تقنية الآخر ولا يخططون أو يعملون على ترجمة الأعمال الفلسفية والعلمية والأدبية التي كانت وراء تلك التقنية.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لم أعش طفولة كما يقول الأطفال الذين عاشوها. فأنا ولدت في قرية فقيرة وأذكر أنني منذ ولادتي كنت في الحقل مع الشجر والنباتات والنهر، في فني أبحث عبر شيخوختي عن طفولتي المفقودة التي اقترب حزنها من حلم الفرح.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "بقدر ما يتقدم الإنسان في العمر يعود في فكره أكثر فأكثر إلى طفولته خصوصا إن كانت حياته حينها صعبة ولا يخجل من تذكرها.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "ما نحتاج إليه هو نشر ما نكتب أي الكلام بحرية في شتى المواضيع وأن نصل إلى تلك المرحلة. فإن لم نعرف أنفسنا فلن نكتشفها ولن يعرف الآخر أيضا.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "الفنان العظيم بقدر ما يشعر أنه يتقدم يشعر بمسؤولية أكبر.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أليس علينا إذاً أن نؤمن بأن الإنسان يحتاج إلى ولادات متعددة ومتواصلة لكي يكون نفسه؟...أليس علينا كذلك، إن شئنا أن نقرأ حقاً، أن نبدأ فنُقصي عنّا، بعناية وإتقان، عدداً كبيراً من الكُتب؟", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "ليس هناك حظٌّ يهبطُ عليك من خارج: من الواقع، أو من الغيب. أنت نفسك حظُّ نفسك.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "الشاعر يفكك العلاقات التقليدية بين اللغة والأشياء في العالم، هذا المُهِم في الشاعر.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "يستحيل الخلاص من الايديولوجيا، لكن أن تكون الايدولوجيا كموجه لكل شيء (هذا يقتل)؛ هذا يجعل الإنسان يسير كالأعمى في اتجاه واحد. الخلاقُ كالشجرة يرى في جميع الاتجاهات، لكي يعرف النور من أين يأتي.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "ألفاظٌ ذات مدلولات دينية وطائفية في عمل سياسي أكون ضده كليا.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أنا لا أؤمن بوحدة قومية مركزية عربية إطلاقا ويكون مركزها هذا البلد أو ذاك. أنا أؤمن بمجتمعات عربية تتحد في ولايات ضمن وحدة ثقافية واقتصادية عربية على غرار الولايات المتحدة الأمريكية.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أنا ضد الدين بوصفه مؤسسة أو دولة أنا ضده بالمطلق حين يصبح هكذا.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لا يمكن أن يكون الشعر وسيلة لأي شيء وكل شيء يجب أن يكون وسيلة من أجل الشعر، أنا أريد أن أكتب لكي أخرج قارئي من نفسه أعلن حربا بداخله أجعله يقلق ويتمزق.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أنا ضد الدولة العربية المركزية الواحدة بل مع الثقافة العربية الواحدة والاقتصاد العربي الموحد.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لا هوية لشعب ليس لديه إبداعات إذا غابت الابداعات أصبحنا قطعان بشرية.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لا أظن أن الانتماء القومي انتهى، أو سينتهي. ربما يحصل ذلك عند أفراد. لكن، أستبعد ذلك عند الشعوب. فيما يتعلق بي صرت بعيدًا جدًا عن النظر إلى القومية نظرة أيديولوجية سياسية. لكن الانتماء إلى لغة وشعب وثقافة شيء آخر، وهو أمرٌ مفروض بحكم الطبيعة والواقع.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لا يتمّ تغيير المجتمع بمجرّد تغيير حُكّامه. قد ينجح هذا التغيير في إحلال حُكّامٍ أقلّ تعفّناً، أو أكثر ذكاءً. لكنه لا يحلّ المشكلات الأساسية التي تُنتج الفساد والتخلّف. إذاً، لا بُد في تغيير المجتمع من الذهاب إلى ما هو أبعد من تغيير الحكّام، وأعني تغيير الأسس الاجتماعية، الاقتصادية، الثقافية.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "موقفي المناوئ والمعارض للنظام القائم ليس وليد هذه الاحتجاجات إنما هو يرجع إلى عهد قديم. فمنذ حوالي 50 سنة وأنا في صراع متواصل مع ديكتاتورية النظام القائم، لذلك أنا بالطبيعة وتلقائيا ضده، إنما قد نختلف في طرق المعارضة.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أنا لا أحبذ طرق العنف بجميع أشكالها مهما كانت مسوغة بحسب أصحابها، لا من جهة النظام أطيقها وقد رفضتها باستمرار ولا من جهة من يعارض هذا النظام...", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أنا مع المعارضة السلمية، معارضة على الطريقة الغاندية...", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أنا أعتقد أن المعارضة يجب أن تؤسس لأخلاقية جديدة ولقيم جديدة، كي تستطيع أن تبني مجتمعا جديدا، هذا شيء قد نختلف فيه.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لا يمكن بناء مجتمع جديد في سوريا ولا في أي مجتمع عربي آخر إلا بالفصل الكامل بين الدين والدولة على جميع المستويات الدينية والاجتماعية والثقافية والسياسية.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لا نستطيع أن نثور على القرون الوسطى بعقلية القرون الوسطى ذاتها. وبهذا المعنى قلت لا أستطيع أن أخرج من الجامع بشعارات سياسية، مع احترامي الكبير لجميع الأديان والمتدينين الأفراد.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "الخروج من الجامع بشعارات سياسية، باسم الدين، هذا هو الذي أنا ضده، ولست ضد الخروج من الجامع في المطلق، لو خرجوا من الجامع دون شعارات سياسية، يستخدم فيها الدين، كنت معهم.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أنا لا أؤمن بالدين إطلاقا.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "النقد هو على الأساس لا على الألفاظ ، في النهاية تصبح نوعا من المماحكة", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "الفرد العربي لكي يكون عربيا يجب أن يكون إنسانيا، يجب أن يكون ألمانيا وفرنسيا وأمريكيا. يعني الذات صارت محل لاحتضان الآخر. بقدر ما نحتضن الآخر نصبح أنفسنا. لا وجود للذات بدون الآخر.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لا أحد يستطيع الدفاع عن أي نظام عربي كان. لكن لا ينبغي أيضا اصلاح الشر الذي تمثله هذه الأنظمة بشر آخر. هذا تماما ما تفعله فرنسا واوروبا اليوم.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لا يمكن أن تضع قانونًا واحدًا صالحًا لجميع المواطنين داخل البلد الواحد إذا لم تفصل الدين عن الدولة.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "كل المنظومات المشابهة للنظام السوري هي ساقطة.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "إن المعارضة السورية ليس لديها خطاب واضح يفصل الدين عن الدولة وينادي بالديمقراطية والمساواة والعلمانية وتحرير المرأة من الشرع الذي يلغي هويتها.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "صوت الرصاص قد يكون الأعلى شكلياً، ولكن يظل صوت الفن و الحب و الصداقة هو الأعمق، فصوت الرصاص عنفي وغير إنساني وضد الحضارة والتقدم، على عكس الفن والثقافة.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "الأطروحات والأفكار والقطائع التي حدثت بدءً من القرن الثاني الهجري/الثامن الميلادي وبشكل خاص في بغداد، أكثر جرأة وأكثر عمقا وأكثر جذرية من أطروحاتنا المعاصرة اليوم.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "ما هو المشروع العربي اليوم للوقوف في وجه التطرف الديني؟ أين هو؟ ماذا تقدم الأنظمة؟ .. والجواب ليس لدينا أي مشروع.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لا يوجد ما يسمى تجديد للدين. فكل تجديد للدين هو دين جديد لكن يمكن أن نغير تأويلنا للدين. كل تأويل هو تقويل للنص. نأول النص أي نفرض عليه أن يقول شيئا مختلفا.. فالتأويل تقويل.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أي نص مهما كان عظيما إذا مر في عقل صغير فإن هذا النص يصغر وإذا مر في عقل كبير فهذا النص على العكس يكبر.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "ليس هناك إسلام حقيقي وإسلام غير حقيقي إنما قد يكون هناك مسلمون معتدلون ومسلمون متطرفون تبعا لقراءاتهم وتأويلاتهم .. لكن الإسلام واحد.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أول قطيعة يجب أن تقوم في الثقافة العربية الراهنة هي القطيعة مع القراءة السائدة للدين وقراءة جديدة للدين.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "ليس هناك أي نص ينص على أن الإسلام دولة، أو على أن الدين دولة، والرسول تحدث في جميع الأشياء حتى في الأشياء الخصوصية للإنسان الفرد لكنه لم يتحدث مرة واحدة عن الدولة الإسلامية التي يجب أن تقام.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لا مفر لنا من الديمقراطية لأنه بدون الديمقراطية لا حرية ولا حقوق ولا مساواة.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أعطني مثلا واحدا على أنّ السياسة الأميركية وقفت إلى جانب الشعوب المستضعفة أو المرتهنة وحرّرتها أو ساعدتها في التحرر.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "إذا كان الإنسان المفكر غير حرّ في جسده، وغير حرّ في رأيه أو تفكيره، وغير حرّ في تنقلّه في زمن الثورة، فكيف نفكّر؟ أين الثورة؟", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "طوال أربعة عشر قرناً لم يستطع العرب تحقيق المواطنة. بينما حقق الرومان ذلك في جميع أنحاء الامبراطورية، ومنحوا الجنسيّة الرومانيّة لجميع الرعايا. العرب لم يستطيعوا أن يفكّكوا بنية القبيلة ولا بنية العشيرة، ولا البنية المذهبية. لم نقم بأي شيء جذري.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أنا أعتقد أنه بدلاً من الدعوات القومية الواحدية العربية على طريقة القرن التاسع عشر والقرن العشرين، يجب العمل على أساس مدني علماني.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "إن من دون تحويل قراءة الدين إلى قراءة جديدة، بحيث لا أحد يحارب أحداً، وتصبح جميع الأديان عبارة عن إيمان شخصي فردي حرّ، ويكون دين المجتمع هو الإنسان وحريته وحقوقه، فإن من دون ذلك لا يمكن إنجاز أي تقدّم.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أن علينا تأسيس جبهة مدنية على امتداد العالم العربي.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لا توجد حلول جاهزة إلا في الدين والإيديولوجيات. ونحن جرّبنا الدين فقتلنا، وجرّبنا الإيديولوجيات فقتلتنا.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "العرب ليس لهم حضور خلاق كأمم وشعوب، بل هم، في نظر الخارج، مجرّد فضاء إستراتيجي، ومجرد ثروات.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "نحن العرب أفراد كسالى، يجب أن ننتقد أنفسنا دائماً. كما تقول الآية: إنّ الله لا يغيّر ما بقوم حتى يغيّروا ما بأنفسهم.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "كيف سنخرج؟ علينا أن نفتح الباب، أي فصل الدين عن الدولة، أي أنّ مدنية المجتمع هي الخطوة الأولى. ولكنها ليست كافية طبعاً.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "...ولكن من دون علمنة المجتمع ومدنيته لا نستطيع أن نقوم بأيّ شيء. ... يجب أن نتأكد أن المجتمع لا يتغير إلا إذا تغيّرت المؤسسة.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "الدين لا يتم إصلاحه. الدين إما أن تؤمن به أو لا تؤمن.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "يجب ألا نقارن أنفسنا بالغرب. أي هل كان الغرب سيئاً أو عظيماً.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "في ثقافتنا العربية، وهي ثقافة وظيفية، والمثقف موظف، فلا تتم قراءة النص كنص، بل يُقرَأ كاتبه. مَن هو؟ ما هي انتماءاته؟ في أي حزب هو؟ أما النص فلا يُقرَأ. والمثقف العربي إجمالا تابع أو موظف ليست لديه حرية كاملة.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "نحن العرب نكتب قصيدة عن وردة قد تكون جميلة، لكن فكرنا محصور في هذه الوردة نفسها. لا يوجد أي خلفيّة إنسانية أو ثقافية خلفها. القصيدة يجب أن تكون شريحة كبيرة، ضمن حدودها. يجب أن يشعر القارئ أن هذه القصيدة مفتوحة على جميع الاتجاهات...", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أنا أفضل كاتبا يكتب رواية باللغة العامية على كاتب يكتب لغة عربية «كرشونية».", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "المأساة الكبرى، هي أن هذا الإسلام الذي جاء بهذه الثورة اليوم، يتحوّل إلى الهرب من كل تجربة روحيّة كبرى، ليصبح مجرّد سلطة. لدينا مليار ونصف المليار مسلم في الكرة الأرضية، ليس فيهم مفكر إسلامي واحد.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "ما دام الحب موجوداً فالشعر موجود.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أعظم شيء في الشعر أنه لا يُحدّد. متى حدّدت الشعر قتلته. وهو قابل لأن يتخذ جميع الأشكال.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "ما هو الفن إجمالاً؟ أن تعطي أسماء جديدة للأشياء، وأن تسمّي الكون من جديد. الكلمة اليوم قاصرة عن ذلك، إما بسبب منها، أو منا، أو بسبب الوضع الثقافي العام والوضع السياسي.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لا يوجد أي إنسان يحلم الحلم ذاته الذي يحلمه آخر، حتى لو كان شقيقه. نحن نشترك في العموميات فحسب.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "النقطة الأساسية أننا بحاجة ماسة إلى إعادة قراءة الموروث ولفظ تاريخ امتداح السلطة القائم على الكذب، والذي أهمل فعل اليد العربية الخلاّقة لمصلحة تمجيد غير الخلاّقين.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "برهن المسلمون أنهم ليسوا في مستوى الرؤية الإسلامية للعالم وربما خسروها وأهملوا كل شيء، والمشكلة تنبع من عندنا، فنحن كسالى وتبعيون وتابعون، وإذا عبّرنا بقليلٍ من الحرية تقمعنا المؤسسة، وصرنا بلا حاضر، وبالتالي بلا مستقبل، وبالمعني الحضاري غير موجودين.. ما نملكه مجرد صفر كبير على الطاولة.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أن الحداثة ليست تطوّراً يطال المركبات والطائرات، وإنما نقلة نوعية في الفكر.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "هناك العديد من المجموعات المعارضة، وأنا دعمت المعارضة الداخلية التي وقفت ضد العنف ويقودها هيثم المناع، لقد تعاونت معهم وأبقى إلى جانبهم...أنا كنت وما أزال ضد المعارضة في الخارج، فهي عنيفة وتقوم على نهج السلطة الدينية، وهي تتعاون أيضاً مع الأمريكيين وكذلك مع الأوروبيين.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "الولايات المتحدة لا يمكن أن تكون إلى جانب الحرية وتحرر الشعوب ولم تكن يوماً إلى جانب الديمقراطيات، فهي متحالفة مع أسوأ الأنظمة في العالم، مع المملكة العربية السعودية وقطر.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "فإذا كانت أوروبا قد تمكنت من فصل الدين عن الدولة، فلماذا لا يتمكن العرب من فعل الشيء نفسه وهم الذين كانوا في التاريخ الباكر متطورين وأحراراً؟", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "الإسلام هو دين شمولي، إنه يفرض حدودا معينة على الحياة الشخصية والخاصة. أما إذا بقي الإسلام عقيدة شخصية ولا يلزم إلا الفرد بحد ذاته، فلا مانع لدي، أنا من مؤيدي تمتع الفرد بالحرية. لقد كنت وسأبقى ضد الإسلام المؤسساتي الذي يفرض بالقوة على المجتمع بأسره .", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أنا تعاملت في كل حياتي مع نظام المعارضة الداخلي، الذي يطالب بالعلمانية والحريات الديمقراطية وبفصل الدين عن الدولة، لأنه يستحيل قيام ديمقراطية أو مجتمع مدني يلزم أفراده بنفس الواجبات، لكن لا يمنحهم نفس الحقوق.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "الديمقراطية تبدأ بفصل الدين عن الدولة.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "الديكتاتورية هي نتيجة لأساس يتمثل بالدين، هو مزج السلطة السياسية بسلطة دينية والأساس يجب أن يتغير.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "حزب البعث الذي حكم سوريا والعراق كان نوعا من الإخوان المسلمين، ولكن باسم آخر", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لم يتميز العصر العباسي بفكره التقدمي. بل عرف بقتل كبار الكتاب والمفكرين مثل الحلاج وشعراء آخرين. ولم يكن متسامحا باستثناء المأمون. أما بقية الخلفاء، فكانوا طغاة وضد الثقافة ولم يشجعوا سوى الفقهاء. حتى المفكرون لم يؤمنوا بالدين الإسلامي رسميا،", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "جميع الذين خلقوا الحضارة الإسلامية لم يكونوا مسلمين بالمعنى الرسمي. وهذه أمور صادمة لأولئك الذين لديهم أفكار خاطئة عن التاريخ العربي الإسلامي. لكن يجب قراءتها من جديد.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لا يجوز للمجتمع القائم على ثقافة دينية أن يتولى الثورة، بل دينك لوحدك مثل الحب لا يلزم أحدا غيرك. أنا لست ضد الدين على الإطلاق، ولكن أنا ضد الدين الذي يُفرض على مجتمع بأكمله فرضا كاملا.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أنا لست سياسيا، أنا انظر إلى السياسة بوصفها جزءا من الثقافة...السياسة مسألة متغيرة، لا علاقة لها بالحقيقة، على عكس الثقافة والفكر. وما ليس له علاقة بالحقيقة فهو لايعبر عني. ولم أكن يوما ما سياسيا وأنا ضد الأدلجة.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أنا أستغرب مثلا مجرد النظر إلى المشكلة السورية على أنها مشكلة نظام فقط، وألّا يتم رؤيتها على أنها مشكلة ثقافية وحضارية وإنسانية. تغيير نظام ديكتاتوري بنظام ديني ثيوقراطي لا يحل المشكلة، بل على العكس يعقدها.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لم يعد الدين حلا للمشكلات؛ لأنه سببها، ولهذا يجب فصله عن الدولة.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لو كان النظام مستبدا فعليك قتاله...لا تدمر البلد، لا تقتل الناس الأبرياء، قاتل النظام.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "عليك الكفاح والوقوف والقتال، أكتب وأسجن.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "أتساءل لماذا السجون العربية ليست مليئة بالكتاب؛ لأنهم لا يقومون بوظيفتهم، ولا ينتقدون، ولا يتحدثون عن القضايا العميقة، القضايا الحقيقية للحياة، ولا يتحدثون عن الأزمات الحقيقية، لكن نقدي هو للكتاب وليس الدولة؛ لأنه يجب أن يكونوا في السجن بسبب قولهم الحقيقة، وهم خارج السجن؛ لأنهم لا يقولون الحقيقة.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "الدين الإسلامي تم التلاعب فيه عبر استخدام مفاهيم الدين نفسه، لكي يصبح أداة سيطرة خالية من الروحانيات.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "في الإسلام الرسمي لا يوجد مفكرون. هناك بعض المتصوفين، ولكن الأغلبية منقادون.. العالم العربي يأتي في المؤخرة من حيث الحداثة، ولكنه أكبر مستهلكي ما تنتجه الحداثة.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "داعش عبارة عن قراءة متطرفة للإسلام، لأن التفسير السائد في الوقت الراهن للإسلام هو التفسير الوهابي.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "بدلا من أن يساعد الغرب القوى الديمقراطية على عدم الخلط بين السياسة والدين، فإنه قام بالنقيض. أيضا لا يجب أن ننسى أن مطالبة إسرائيل بالاعتراف بها مجتمعا للدين اليهودي لعب دورا كارثيا في الدول العربية، ولكن لا أحد يود الحديث عن ذلك.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "الشعر لا يمكن أن يذبح طفلا، ولا أن يقتل إنسانا، ولا أن يدمر متحفا.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "الأمريكيين لا يسعون إلى حلول بل إلى مشاكل. ليست لديهم رؤية متماسكة. والروس كذلك فهم لا يهتمون إلا بمصالحهم. العالم العربي مساحة إستراتيجية زاخرة بالثروات. العرب مجرد وسيلة. فلا اهتمام بحقوق الإنسان والحرية والاستقلال والكرامة البشرية.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "ثورة علمانية لا يمكن تحقيقها عبر أشخاص يخرجون من المساجد.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لو كان في مقدور الإنسان تعريف نفسه، لكانت الأسرار العميقة سطحية. إلّا أن الإنسان الذي لا يعرف، أو الذي لا يُحاول معرفة نفسه والتعريف بها جيداً، سيكون أقل معرفة بالوجود، وأقل معرفة بالحياة.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "الإنسان عالم من الأسرار، كما الشعر. هو سؤال وليس جواباً. وأظن أن أعمق ما يميز الإنسان بين الكائنات هو تلك القدرة التي يمتلكها، قدرته على طرح الأسئلة.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "يكفيني أنني كتبت الشعر كي أفهم نفسي، والعالم، والآخر.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "الهوية ليست حاضرة مسبقاً، كما عند العرب، وعند كثيرين. هي ابتكار متواصل. الآخر عنصر مكون من عناصر تكوين الذات.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "الحب هو الحياة. لكنْ للحب أصول ومتطلبات ليست سهلة على أي إنسان. وفي رأيي الشخصي، لا يوجد حب مطلق، بل هناك حب محدد، حب يقوم على علاقة محددة بين رجل وامرأة.وكل حب لا يمكن أن يشبه سواه.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لا توجد امرأة في الوجود تشبه سواها. كل امرأة هي كيان خاص بذاته، لا يمكن مقارنته بسواه. لكل امرأة عالمها الخاص وجسدها الخاص. وكذلك الأمر بالنسبة إلى الرجل.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "الجمال لا ينحصر في الشكل الخارجي للمرأة، إنما جمالها مبثوث في كل عالمها الداخلي. إن معيار الجمال قائم في الأحاسيس ــ «الكيمياء» بين رجل وامرأة.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "الحب أعمى، والرجل يرى في المرأة كل ما يحبه، لذلك يراها جميلة، وكذلك الأمر بالنسبة إلى جمال الرجل في أحاسيس المرأة.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "وطني الدائم: اللغة العربية. ففي هذه اللغة أفصح عن نفسي وأشعر بأنني موجود فيها وبها.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لا يمكن لأي كاتب أن يكون كاتبا حقيقيا ما لم يكن معارضا للسلطة.. أي سلطة، خاصة تلك السلطة التوتاليرية والدكتاتورية والدينية. وبذا يجب أن تكون كلمته معبرة عن هذا الرفض أو على الأقل النقد الحقيقي للنظام، وإلا لكان بوقا وليس كاتبا.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "إن سوريا تتمتع بخاصية لا مثيل لها في العالم، لما تلم من تاريخ للبشرية وتواصل لهذا الإرث فيها.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "ما مرت وما تمر به سوريا اليوم لا يمكن أن يكون ثورة، كما يحلو للبعض تسميتها، وإنما إساءة إلى فكرة الثورة. لماذا؟ ببساطة، حيث لا يمكن لثورة أن تقوم على أكتاف مرتزقة ومأجورين، ففي سوريا اليوم جنسيات متعددة، من بلدان المنطقة ومن خارجها، تحارب النظام وتحارب بعضها البعض.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "الغرب لا يريد عالما عربيا ديمقراطيا في مستواه.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "لا يمكن أن تخرج ثورة من الجامع إلا وتؤدي إلى الكوارث...", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "ما ننسخ من آية إلا ونأتي بمثلها أو بأحسن منها.. فإذا كان الوحي يتغير رغم صدقه ومطلقيته فكيف الحياة الاجتماعية والإنسانية؟.", Author = "أدونيس" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/أدونيس", Text = "قولي لنا، أيتها الطبيعة-الأرض-الأم،\nوقولي لنا، أنت أيتها «الوحدانية»:\nأهذه هي الإنسانية، حقاً؟/أهذا هو الإنسانُ، حقاً؟\nأليست هذه هي المسألة التي تتيح طرحها بإلحاح على العالم، عالمية الكورونا؟", Author = "أدونيس" },
        };
    }
}